import { createAttemptLimiter, sessionCookie, signSession, verifySession, verifyTotp } from '@pyreon/auth'

const revoked = new Set<string>()
const lastTotpStep = new Map<string, number>() // keep it on the user record in practice
const opts = {
  secrets: [process.env.SESSION_SECRET ?? ''], // ≥ 32 characters; prepend a new one to rotate
  maxAge: 8 * 60 * 60,
  isRevoked: (jti: string) => revoked.has(jti),
}
const limiter = createAttemptLimiter({ max: 5, windowMs: 15 * 60_000 })

// after the password step: check the authenticator code, then issue the cookie
async function secondFactor(user: { id: string; totpSecret: string }, code: string) {
  if (!limiter.attempt(user.id).allowed) return new Response('Try again later', { status: 429 })
  const r = await verifyTotp(user.totpSecret, code, { lastUsedStep: lastTotpStep.get(user.id) })
  if (!r.ok) return new Response('Wrong code', { status: 401 })
  lastTotpStep.set(user.id, r.step) // the same code cannot pass a second time
  limiter.reset(user.id)
  const value = await signSession({ sub: user.id }, opts)
  return new Response(null, { status: 303, headers: { location: '/', 'set-cookie': sessionCookie('session', value, opts.maxAge) } })
}

const whoIs = async (cookieValue: string) => (await verifySession(cookieValue, opts))?.sub ?? null

import { createGuard, safeReturnTo } from '@pyreon/auth'

const requireAdmin = createGuard({
  session: () => (auth.isAuthenticated() ? { role: auth.claim('role') } : null),
  loginPath: '/login',
  allow: (s) => s.role === 'admin',
})

requireAdmin('/admin/users') // true, or { redirect: '/login?returnTo=%2Fadmin%2Fusers' }

// after sign-in: go back, but only to a path on this origin
safeReturnTo('/admin/users') // '/admin/users'
safeReturnTo('//evil.example') // '/'
safeReturnTo('/\t/evil.example') // '/'

import { useOidc } from '@pyreon/auth'
import { Text } from '@pyreon/primitives'
import { useQuery } from '@pyreon/query'

type Me = { name: string; email: string }

function Account() {
  const auth = useOidc({
    issuer: 'https://accounts.example.com',
    clientId: 'app',
    redirectUri: 'https://app.example.com/callback',
    nativeRedirectUri: 'com.example.app:/oauth',
  })
  const me = useQuery<Me>(() => ({
    queryKey: ['me', auth.subject() ?? 'anonymous'], // a new user refetches
    queryFn: () =>
      fetch('https://api.example.com/me', {
        headers: { authorization: `Bearer ${auth.accessToken() ?? ''}` },
      }).then((r) => r.json()),
    enabled: auth.isAuthenticated(),
  }))
  return <Text>{me.data()?.name ?? auth.status()}</Text>
}
